            aOrbiterE = (aWandererI + RotL64(aPrevious, 50U)) + 0xA37082BC0BB9AE0AULL;
            aOrbiterI = (((aWandererH + RotL64(aCross, 41U)) + RotL64(aCarry, 43U)) + 0xA2534AE54FDB4078ULL) + aOASaltE[((aIndex + 383U)) & S_SALT1];
