            //
            aOrbiterF = ((aOrbiterF + aOrbiterA) + 0x235361055DF3B1AEULL) + aOUSaltF[(((511U - aIndex) + 170U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0x575AE2E49012D47AULL;
