            aWandererJ = aWandererJ ^ ((RotL64(aScatter, 11U) + RotL64(aOrbiterC, 3U)) + aOrbiterB);
            aWandererI = aWandererI + ((RotL64(aPrevious, 29U) + RotL64(aOrbiterF, 19U)) + aOrbiterA);
            //
            aCarry = aCarry + (aWandererG ^ RotL64(aWandererF, 43U));
