            aOrbiterK = (aWandererB + RotL64(aCross, 13U)) + 0x72E3C18832A0F5A1ULL;
            aOrbiterC = ((aWandererE + RotL64(aIngress, 19U)) + 0xF295EE2C98480CA3ULL) + aOASaltC[((aIndex + 471U)) & S_SALT1];
