            aOrbiterF = (aWandererK + RotL64(aPrevious, 22U)) + 0x7C98C858A2D107BEULL;
            aOrbiterD = ((aWandererI + RotL64(aCross, 35U)) + 0xEE33366DAE161088ULL) + aOASaltE[((aIndex + 310U)) & S_SALT1];
            aOrbiterJ = ((aWandererA + RotL64(aIngress, 53U)) + RotL64(aCarry, 13U)) + 0x11B11BBC6AD3282CULL;
            aOrbiterB = ((aWandererG + RotL64(aScatter, 27U)) + 0x1D31FCC54E769073ULL) + aOASaltG[(((511U - aIndex) + 413U)) & S_SALT1];
            aOrbiterE = ((aWandererH + RotL64(aPrevious, 41U)) + 0x5874AE1EA34DF042ULL) + aOASaltB[((aIndex + 196U)) & S_SALT1];
            aOrbiterA = ((aWandererJ + RotL64(aCross, 39U)) + 0x6427A64BABDFB7E1ULL) + aOASaltD[(((511U - aIndex) + 281U)) & S_SALT1];
