            aOrbiterG = (aWandererC + RotL64(aScatter, 57U)) + 0x613973D27C8DC61DULL;
            //
            aOrbiterK = ((aOrbiterK + aOrbiterC) + 0xA722813579D67846ULL) + aOUSaltH[((aIndex + 408U)) & S_SALT1];
