            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0xA14ED1974F39646EULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0x0689BEC2C3A2611FULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x52331E503D8363E9ULL), 13U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0xAB10E4473CC12F1EULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0x9818980FC5747C44ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x64CAA472D4F95CEFULL), 23U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0xF0B03562AF79D61EULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0x5F84EE7AA4185AEDULL;
            aOrbiterK = RotL64((aOrbiterK * 0x2F7B7E3A2D255ADFULL), 37U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterI) + 0x9930BFBDD7ED5A4AULL) + aOUSaltC[(((511U - aIndex) + 87U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x8CB04BB949743819ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x78A6E6266822EAF7ULL), 21U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterA) + 0xACE2A4CA72CFCEF6ULL) + aOUSaltF[(((511U - aIndex) + 229U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterE) ^ 0x52FC30E136524993ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xE4B8DB931DD013EDULL), 41U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterH) + 0x9B12462CDA5DE617ULL) + aOUSaltE[(((511U - aIndex) + 211U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterD) ^ 0xE07F552EF5E15311ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x3447E67AB5920227ULL), 11U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x88981FA4AAE8DA61ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0xCF76C3517C270B9EULL;
            aOrbiterB = RotL64((aOrbiterB * 0xB8F453B7984EAB9DULL), 19U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterK) + 0x68E5C3A8C5B6444CULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0x298C6474408E39E3ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xD40EA817C888F7EDULL), 3U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0x62892B89A3ABCD53ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0x61D7D5953DA72489ULL;
