            aWandererD = aWandererD + ((RotL64(aCross, 41U) + RotL64(aOrbiterF, 21U)) + aOrbiterE);
            aWandererC = aWandererC ^ (((RotL64(aIngress, 51U) + RotL64(aOrbiterK, 47U)) + aOrbiterB) + RotL64(aCarry, 19U));
